import type { MetadataRoute } from 'next'
import { brand } from '@/lib/brand'
import { brandIconPalette, brandShortName } from '@/lib/brand-icon'

// Web app manifest, named and coloured from the deployment's brand. The icon
// URLs are the ids generated by src/app/icon.tsx's generateImageMetadata.
export default function manifest(): MetadataRoute.Manifest {
  const palette = brandIconPalette({ primaryColor: brand.primaryColor })
  return {
    name: brand.name,
    short_name: brandShortName(brand.name),
    description: brand.tagline,
    start_url: '/',
    display: 'standalone',
    background_color: palette.background,
    theme_color: palette.themeColorLight,
    icons: [
      { src: '/icon/192', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icon/512', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icon/svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
      { src: '/apple-icon', sizes: '180x180', type: 'image/png', purpose: 'maskable' },
    ],
  }
}
